import { TransportError, type CallOptions, type ProjectTransport } from './projectTransport'

// Browsers cap the bodies of all in-flight keepalive requests at 64 KiB; bigger ones are sent normally.
const KEEPALIVE_MAX_BYTES = 60_000

const bodyBytes = (body: BodyInit | null | undefined) =>
  body == null ? 0 : typeof body === 'string' ? new TextEncoder().encode(body).length : Infinity

// Runs one server-function call with our own fetch so we know whether (and what) the server answered.
async function call<T>(run: (fetch: typeof globalThis.fetch) => Promise<T>, opts?: CallOptions): Promise<T> {
  let response: Response | undefined
  const tracked = async (input: RequestInfo | URL, init?: RequestInit) => {
    const keepalive = !!opts?.keepalive && bodyBytes(init?.body) < KEEPALIVE_MAX_BYTES
    response = await fetch(input, keepalive ? { ...init, keepalive } : init)
    return response
  }
  try {
    return await run(tracked as typeof globalThis.fetch)
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err)
    // No response at all: offline, server restarting, request aborted.
    if (!response) throw new TransportError('Server je nedostupný', true)
    // An error thrown by our server function arrives serialized: the server rejected this request (validation, …).
    if (response.headers.get('x-tss-serialized')) throw new TransportError(message, false)
    // A bare error page (proxy, gateway): 5xx/408/429 are transient, other 4xx will not get better by retrying.
    const transient = response.status >= 500 || response.status === 408 || response.status === 429
    throw new TransportError(`Server odpovedal chybou ${response.status}`, transient)
  }
}

